        let mut governor = PerfGovernor::new();
        // rAF on a 60Hz display floors at ~16.7ms even with GPU headroom.
        for _ in 0..600 {
            governor.update(16.7);
        }
        assert_eq!(governor.scale(), 1.0, "must reach native res under vsync");
    }

